[
  {
    "sys_fairness_reciprocity": "Three each at least matches the load.",
    "pda_responsibility": "My own choices got me into this room.",
    "pda_repair_intention": "lay out exactly what I did, no shading"
  },
  {
    "ce_understood_harm": "their three years would be on me",
    "pd_decision_conflict": "I'm honestly not sure.",
    "sys_fairness_reciprocity": "doesn't balance",
    "pda_responsibility": "I'd be the one who added them.",
    "pda_repair_intention": "ask my lawyer to tell the judge"
  },
  {
    "sys_fairness_reciprocity": "Equal time seems closer to right than five and zero.",
    "pda_responsibility": "I went into that warehouse knowing what I was doing",
    "pda_repair_intention": "write a plain account for the court owning my share"
  },
  {
    "pd_decision_conflict": "Both options sit in my stomach like a stone.",
    "sys_fairness_reciprocity": "the one who talked first walks while the one who didn't pays for both? That feels off",
    "pda_responsibility": "nobody forced me there",
    "pda_repair_intention": "meet whoever was hurt by the warehouse business"
  },
  {
    "ce_understood_harm": "putting three years on someone",
    "sys_fairness_reciprocity": "matching that seems like evening things out",
    "pda_responsibility": "I know what I did that day.",
    "pda_repair_intention": "draft something for the court setting out my own part honestly"
  },
  {
    "pd_decision_conflict": "scared of picking wrong either way",
    "sys_fairness_reciprocity": "ought to line up with what each of us did",
    "pda_responsibility": "I also chose to be there.",
    "pda_repair_intention": "put part of whatever I earn inside toward any damage"
  },
  {
    "pd_decision_conflict": "I genuinely can't settle it yet.",
    "sys_fairness_reciprocity": "carrying both our shares, and I'm not sure I can swallow that.",
    "pda_responsibility": "My hands are in it as much as theirs.",
    "pda_repair_intention": "ask the prosecutor to note their early cooperation"
  },
  {
    "ce_understood_harm": "feel five years just as much as I will",
    "sys_fairness_reciprocity": "we both answer equally for one shared act",
    "pda_responsibility": "That was my call, not theirs.",
    "pda_repair_intention": "sit down with my family, explain exactly what I did"
  },
  {
    "pd_decision_conflict": "I think I'd testify, but I'm not certain",
    "sys_fairness_reciprocity": "equal time makes more sense than a lopsided deal",
    "pda_responsibility": "I won't hide that my choices got me here.",
    "pda_repair_intention": "correct anything I get wrong the moment I realize it"
  },
  {
    "pd_decision_conflict": "Every option here costs something, and I keep circling.",
    "sys_fairness_reciprocity": "answering the same way just brings us level",
    "pda_responsibility": "It would be my decision, nobody else's.",
    "pda_repair_intention": "write to the court through my lawyer, acknowledging my part"
  }
]
